import React,{useState,useEffect,useMemo,useRef} from 'react';
import {createRoot} from 'react-dom/client';
import {LayoutDashboard,Package,Layers3,Tags,MessagesSquare,Truck,ChartNoAxesCombined,Settings2,ArrowUpRight,ArrowRight,RefreshCw,Upload,Search,Plus,ChevronLeft,ChevronRight,Check,Download,SlidersHorizontal,ShieldCheck,LogOut,Menu,Activity,FileCheck2,Send,Save,Clock3,Link2,CheckCheck,AlertTriangle,ArrowDownToLine,Sparkles,X} from 'lucide-react';
