 {rows.length?<div className="draft-grid">{rows.map(d=><div className="draft-wrapper" key={d.id}><label className="draft-select"><input type="checkbox" aria-label={'Seleccionar propuesta '+d.sku} disabled={d.status==='published'} checked={selected.includes(d.id)} onChange={()=>toggle(d.id)}/></label><button className="draft-card" onClick={()=>setModal({type:'draft',id:d.id})}><div className="draft-art">{d.payload.pictures[0]?.source&&/^https:\/\//.test(d.payload.pictures[0].source)?<img alt="Imagen de la propuesta" src={d.payload.pictures[0].source}/>:<><Layers3 size={34}/><span>Imagen por incorporar</span></>}<Status value={d.status}/></div><div className="draft-info"><span className="code">{d.sku}</span><h3>{d.payload.title}</h3><strong>{money(d.payload.price_cents)}</strong><div className="draft-meta"><span>{d.issues.length?`${d.issues.length} puntos por completar`:'Lista para validar'}{d.payload.video_pending?' · video pendiente':''}</span><ArrowUpRight size={18}/></div></div></button></div>)}</div>:<section className="panel"><Empty title="El próximo lote empieza en el catálogo" action={<Button icon={Plus} variant="primary" onClick={()=>go('catalog')}>Elegir productos</Button>}>Seleccioná productos y prepará propuestas. Las revisás antes de publicarlas.</Empty></section>}
 {template&&<TemplateModal drafts={chosen} sameFamily={new Set(chosen.map(d=>productFamily(d.sku))).size===1} act={act} busy={busy} onClose={()=>setTemplate(false)}/>}
